from typing import Optional, List, Dict, Any
from pydantic import BaseModel, Field, ConfigDict, field_validator
from app.schemas.auth import UserSimple
from app.schemas.timestamps import UTCDateTime


class ActionValidation(BaseModel):
    status: str  # VALID | ADVISORY | INVALID
    errors: List[str] = []
    warnings: List[str] = []


class ProposedAction(BaseModel):
    action_id: str
    action_type: str
    task_id: int
    task_title: str
    original_values: Dict[str, Any]
    proposed_values: Dict[str, Any]
    reason: str
    expected_impact: str
    # "AI" when generated by the language model, "RULE" when produced by the
    # rule-based planner. Older proposals have no source recorded.
    source: Optional[str] = None
    is_advisory: bool = False
    validation: Optional[ActionValidation] = None


class LLMTrace(BaseModel):
    invoked: bool = False
    provider: Optional[str] = None
    model: Optional[str] = None
    status: Optional[str] = None
    error: Optional[str] = None
    error_category: Optional[str] = None
    latency_ms: Optional[int] = None
    skip_reason: Optional[str] = None
    prompt_version: Optional[str] = None


class GenerationTrace(BaseModel):
    """How a proposal was produced. Empty for proposals created before
    tracing was added."""

    run_id: Optional[str] = None
    status: Optional[str] = None
    started_at: Optional[str] = None
    completed_at: Optional[str] = None
    generation_mode: Optional[str] = None  # AI_HYBRID | RULE_BASED_FALLBACK | RULE_BASED
    llm: Optional[LLMTrace] = None
    graph_nodes: List[str] = []
    deterministic_findings: Dict[str, Any] = {}
    ai_analysis: Optional[Dict[str, Any]] = None
    selected_strategy_id: Optional[str] = None
    selection_reason: Optional[str] = None
    strategies: List[Dict[str, Any]] = []
    rejected_actions: List[Dict[str, Any]] = []
    validation: Dict[str, Any] = {}
    schedule_comparison: Dict[str, Any] = {}


class ProposalDecisionCreate(BaseModel):
    decision: str = Field(..., pattern="^(APPROVED|REJECTED|DEFERRED)$")
    decision_notes: Optional[str] = None


class ProposalDecisionOut(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    @field_validator("execution_report", mode="before", check_fields=False)
    @classmethod
    def _empty_report(cls, value):
        return value or {}

    id: int
    proposal_id: int
    decider_id: int
    decision: str
    decision_notes: Optional[str] = None
    applied_changes: List[Dict[str, Any]] = []
    execution_report: Dict[str, Any] = {}
    decided_at: UTCDateTime
    decider: Optional[UserSimple] = None


class FocusContextEvidence(BaseModel):
    id: int
    task_id: int
    task_title: str
    user_id: int
    employee_name: str
    reason: str
    context: str
    created_at: UTCDateTime


class RecoveryProposalOut(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    project_id: int
    risk_analysis_id: Optional[int] = None
    title: str
    summary: str
    proposed_actions: List[ProposedAction] = []
    focus_contexts: List[FocusContextEvidence] = []
    rationale: str
    assumptions: List[str] = []
    status: str
    created_at: UTCDateTime
    decisions: List[ProposalDecisionOut] = []
    generation_trace: GenerationTrace = Field(default_factory=GenerationTrace)

    @field_validator("generation_trace", mode="before")
    @classmethod
    def _empty_trace(cls, value):
        return value or {}
